// Obst is an adapted arrangement of apple, banana, grapes, peach and watermelon.
const LETTER_ART: Record<string, string> = {
  "Ast": "data:image/svg+xml;base64,",
  "Boot": "data:image/svg+xml;base64,",
  "Chef": "data:image/svg+xml;base64,",
  "Dose": "data:image/svg+xml;base64,",
  "Ente": "data:image/svg+xml;base64,",
  "Äpfel": "data:image/svg+xml;base64,",
  "Fisch": "data:image/svg+xml;base64,",
  "Gans": "data:image/svg+xml;base64,",
  "Hut": "data:image/svg+xml;base64,",
  "Igel": "data:image/svg+xml;base64,",
  "Jacke": "data:image/svg+xml;base64,",
  "Öl": "data:image/svg+xml;base64,",
  "Krebs": "data:image/svg+xml;base64,",
  "Lampe": "data:image/svg+xml;base64,",
  "Maus": "data:image/svg+xml;base64,",
  "Nest": "data:image/svg+xml;base64,",
  "Obst": "data:image/svg+xml;base64,",
  "Tür": "data:image/svg+xml;base64,",
  "Palme": "data:image/svg+xml;base64,",
  "Qualle": "data:image/svg+xml;base64,",
  "Rose": "data:image/svg+xml;base64,",
  "Sonne": "data:image/svg+xml;base64,",
  "Tau": "data:image/svg+xml;base64,",
  "Fuß": "data:image/svg+xml;base64,",
  "Uhr": "data:image/svg+xml;base64,",
  "Vogel": "data:image/svg+xml;base64,",
  "Wal": "data:image/svg+xml;base64,",
  "Xylofon": "data:image/svg+xml;base64,",
  "Yacht": "data:image/svg+xml;base64,",
  "Zug": "data:image/svg+xml;base64,"
};

export default function GermanLetterArt({ word, size, color }: {
  word: string; size: number; color: string;
}) {
  const src = LETTER_ART[word];
  if (!src) return <span style={{ fontSize: size * 0.3, lineHeight: 1 }}>{word}</span>;
  return <img src={src} alt={word} width={size} height={size}
    draggable={false}
    style={{ width: size, height: size, objectFit: 'contain', display: 'inline-block',
      verticalAlign: 'middle', flexShrink: 0, filter: `drop-shadow(0 4px 8px ${color}aa)` }} />;
}
